17	)
18	
19	type GorgoniteConfig struct {
20		VocabSize    int
21		EmbedDim     int
22		NumHeads     int
23		NumLayers    int
24		ContextLen   int
25		DropoutRate  float64
26		FFNHiddenDim int
27	}
28	
29	func DefaultGorgoniteConfig() *GorgoniteConfig {
30		return &GorgoniteConfig{
31			VocabSize:    100277,
32			EmbedDim:     768,
33			NumHeads:     12,
34			NumLayers:    12,
35			ContextLen:  2048,
36			DropoutRate: 0.1,
37			FFNHiddenDim: 3072,
38		}
39	}
40	
41	type EmbeddingLayer struct {
42		graph      *gorgonia.ExprGraph
43		embeddings *gorgonia.Node
44		vocabSize  int
45		embedDim   int
46		seqLen     int
47	}
48	
49	func NewEmbeddingLayer(g *gorgonia.ExprGraph, vocabSize, embedDim, seqLen int) *EmbeddingLayer {
50		embeddings := gorgonia.NewMatrix(g,
51			tensor.Float32,
52			gorgonia.WithShape(seqLen, embedDim),
53			gorgonia.WithName("embeddings"),
54			gorgonia.WithInit(gorgonia.GlorotN(1.0)),
55		)
56	
57		return &EmbeddingLayer{
58			graph:     g,
59			embeddings: embeddings,
60			vocabSize: vocabSize,
61			embedDim:  embedDim,
62			seqLen:    seqLen,
63		}
64	}
65	
66	func (e *EmbeddingLayer) Forward(seqLen int) (*gorgonia.Node, error) {
67		return e.embeddings, nil
68	}
69	
70	type PositionalEncoding struct {
71		graph    *gorgonia.ExprGraph
72		encoding *gorgonia.Node
73		seqLen   int
74		embedDim int
75	}
76	
77	func NewPositionalEncoding(g *gorgonia.ExprGraph, seqLen, embedDim int) *PositionalEncoding {
78		encoding := make([]float32, seqLen*embedDim)
79	
80		for pos := 0; pos < seqLen; pos++ {
81			for i := 0; i < embedDim; i++ {
82				angle := float64(pos) / math.Pow(10000, float64(2*i)/float64(embedDim))
83				if i%2 == 0 {
84					encoding[pos*embedDim+i] = float32(math.Sin(angle))
85				} else {
86					encoding[pos*embedDim+i] = float32(math.Cos(angle))
87				}
88			}
89		}
90	
91		posEncTensor := tensor.New(
92			tensor.WithBacking(encoding),
93			tensor.WithShape(seqLen, embedDim),
94		)
95	
96		posEncNode := gorgonia.NewConstant(posEncTensor, gorgonia.WithName("pos_encoding"))
97	
98		return &PositionalEncoding{
99			graph:    g,
100			encoding: posEncNode,
101			seqLen:   seqLen,
102			embedDim: embedDim,
103		}
104	}
105	
106	func (p *PositionalEncoding) Forward(seqLen int) (*gorgonia.Node, error) {
107		return p.encoding, nil
108	}
109	
110	type SelfAttention struct {
111		graph    *gorgonia.ExprGraph
112		wQuery   *gorgonia.Node
113		wKey     *gorgonia.Node
114		wValue   *gorgonia.Node
115		embedDim int
116		headDim  int
117		dropout  float64
118	}
119	
120	func NewSelfAttention(g *gorgonia.ExprGraph, embedDim, headDim int, dropout float64, seqLen int) *SelfAttention {
121		wq := gorgonia.NewMatrix(g, tensor.Float32,
122			gorgonia.WithShape(embedDim, headDim),
123			gorgonia.WithName("w_query"),
124			gorgonia.WithInit(gorgonia.GlorotN(1.0)),
125		)
126	
127		wk := gorgonia.NewMatrix(g, tensor.Float32,
128			gorgonia.WithShape(embedDim, headDim),
129			gorgonia.WithName("w_key"),
130			gorgonia.WithInit(gorgonia.GlorotN(1.0)),
131		)
132	
133		wv := gorgonia.NewMatrix(g, tensor.Float32,
134			gorgonia.WithShape(embedDim, headDim),
135			gorgonia.WithName("w_value"),
136			gorgonia.WithInit(gorgonia.GlorotN(1.0)),
137		)
138	
139		return &SelfAttention{
140			graph:    g,
141			wQuery:   wq,
142			wKey:     wk,
143			wValue:   wv,
144			embedDim: embedDim,
145			headDim:  headDim,
146			dropout:  dropout,
147		}
148	}
149	
150	func (sa *SelfAttention) Forward(x *gorgonia.Node, mask *gorgonia.Node, training bool) (*gorgonia.Node, error) {
151		q, err := gorgonia.Mul(x, sa.wQuery)
152		if err != nil {
153			return nil, err
154		}
155	
156		k, err := gorgonia.Mul(x, sa.wKey)
157		if err != nil {
158			return nil, err
159		}
160	
161		v, err := gorgonia.Mul(x, sa.wValue)
162		if err != nil {
163			return nil, err
164		}
165	
166		kT, err := gorgonia.Transpose(k)
167		if err != nil {
