1	package transformer
2	
3	import (
4		"fmt"
5		"regexp"
6		"strings"
7	)
8	
9	type BidirectionalVerifier struct {
10		wazeroGate  *WazeroGate
11		hashNet    *HashNetworkWrapper
12		confidence float32
13	}
14	
15	func NewBidirectionalVerifier() *BidirectionalVerifier {
16		return &BidirectionalVerifier{
17			wazeroGate:  NewWazeroGate(),
18			hashNet:    NewHashNetworkWrapper(),
19			confidence: 0.0,
20		}
21	}
22	
23	func (bv *BidirectionalVerifier) Verify(source, wasmType string) (bool, float32, string) {
24		forwardPassed, forwardMsg := bv.verifyForward(source, wasmType)
25		backwardPassed, backwardMsg := bv.verifyBackward(source, wasmType)
26	
27		bv.confidence = calculateConfidence(forwardPassed, backwardPassed, forwardMsg, backwardMsg)
28	
29		if forwardPassed && backwardPassed {
30			return true, bv.confidence, fmt.Sprintf("Forward: %s | Backward: %s", forwardMsg, backwardMsg)
31		}
32	
33		return false, bv.confidence, fmt.Sprintf("Forward: %s | Backward: %s", forwardMsg, backwardMsg)
34	}
35	
36	func (bv *BidirectionalVerifier) verifyForward(source, wasmType string) (bool, string) {
37		valid, errMsg := bv.wazeroGate.Validate(source)
38		if !valid {
39			return false, fmt.Sprintf("wazero compile failed: %s", errMsg)
40		}
41	
42		if !hasValidExports(source, wasmType) {
43			return false, "no valid exports found"
44		}
45	
46		return true, "forward pass OK"
47	}
48	
49	func (bv *BidirectionalVerifier) verifyBackward(source, wasmType string) (bool, string) {
50		if !bv.hashNet.IsAvailable() {
51			return true, "hashnet unavailable, backward skipped"
52		}
53	
54		hashMatches := bv.hashNet.VerifySource(source)
55		if !hashMatches {
56			return false, "hashnet hash mismatch"
57		}
58	
59		if !matchesBackwardInvariant(source, wasmType) {
60			return false, "backward invariant violation"
61		}
62	
63		return true, "backward pass OK"
64	}
65	
66	func hasValidExports(source, wasmType string) bool {
67		var expectedExport string
68		switch wasmType {
69		case "rule":
70			expectedExport = "GuardrailClass"
71		case "resolution":
72			expectedExport = "ErrorClass"
73		case "patch":
74			expectedExport = "PatchScope"
75		default:
76			return false
77		}
78	
79		return strings.Contains(source, "//export "+expectedExport)
80	}
81	
82	func matchesBackwardInvariant(source, wasmType string) bool {
83		exportPattern := regexp.MustCompile(fmt.Sprintf(`(?m)^//export %s`, wasmType))
84		return exportPattern.MatchString(source)
85	}
86	
87	func calculateConfidence(forwardPassed, backwardPassed bool, forwardMsg, backwardMsg string) float32 {
88		confidence := float32(0.0)
89	
90		if forwardPassed {
91			confidence += 0.5
92		}
93		if backwardPassed {
94			confidence += 0.5
95		}
96	
97		if strings.Contains(forwardMsg, "OK") && strings.Contains(backwardMsg, "OK") {
98			confidence = 1.0
99		}
100	
101		return confidence
102	}
103	
104	type ForwardVerifier struct {
105		wazeroGate *WazeroGate
106	}
107	
108	func NewForwardVerifier() *ForwardVerifier {
109		return &ForwardVerifier{
110			wazeroGate: NewWazeroGate(),
111		}
112	}
113	
114	func (fv *ForwardVerifier) Verify(source string) (bool, string, error) {
115		valid, errMsg := fv.wazeroGate.Validate(source)
116		if !valid {
117			return false, errMsg, nil
118		}
119	
120		results, err := fv.wazeroGate.Run()
121		if err != nil {
122			return false, err.Error(), err
123		}
124	
125		if len(results) > 0 {
126			return true, fmt.Sprintf("verified with %d exports", len(results)), nil
127		}
128	
129		return false, "no exports", nil
130	}
131	
132	func (fv *ForwardVerifier) Close() error {
133		return fv.wazeroGate.Close()
134	}
135	
136	type BackwardVerifier struct {
137		hashNet *HashNetworkWrapper
138	}
139	
140	func NewBackwardVerifier() *BackwardVerifier {
141		return &BackwardVerifier{
142			hashNet: NewHashNetworkWrapper(),
143		}
144	}
145	
146	func (bv *BackwardVerifier) Verify(source string, wasmType string) (bool, string) {
147		if !bv.hashNet.IsAvailable() {
148			return true, "hashnet unavailable"
149		}
150	
151		hashMatches := bv.hashNet.VerifySource(source)
152		if !hashMatches {
153			return false, "hashnet hash mismatch"
154		}
155	
156		invariantMatches := matchesBackwardInvariant(source, wasmType)
157		if !invariantMatches {
158			return false, "invariant mismatch"
159		}
160	
161		return true, "backward verified"
162	}
163	
164	type VerificationResult struct {
165		Passed           bool
166		Confidence      float32
167		ForwardMsg      string
168		BackwardMsg     string
169		ForwardErrors   []string
170		BackwardErrors []string
171	}
172	
173	func NewVerificationResult() *VerificationResult {
174		return &VerificationResult{
175			ForwardErrors:   []string{},
176			BackwardErrors: []string{},
177		}
178	}
179	
180	func (vr *VerificationResult) Merge(other *VerificationResult) {
181		if other.Passed {
182			vr.Passed = true
183		}
184		vr.Confidence = (vr.Confidence + other.Confidence) / 2
185	
186		if other.ForwardErrors != nil {
187			vr.ForwardErrors = append(vr.ForwardErrors, other.ForwardErrors...)
188		}
189		if other.BackwardErrors != nil {
190			vr.BackwardErrors = append(vr.BackwardErrors, other.BackwardErrors...)
191		}
192	}
193	
194	type VerifierPool struct {
195		forwardVerifiers  []*ForwardVerifier
196		backwardVerifiers []*BackwardVerifier
197		size            int
198		index          int
199	}
200	
201	func NewVerifierPool(size int) *VerifierPool {
202		return &VerifierPool{
203			forwardVerifiers:  make([]*ForwardVerifier, size),
204			backwardVerifiers: make([]*BackwardVerifier, size),
205			size:            size,
206			index:          0,
207		}
208	}
209	
210	func (vp *VerifierPool) AcquireForward() *ForwardVerifier {
211		if vp.forwardVerifiers[vp.index] == nil {
212			vp.forwardVerifiers[vp.index] = NewForwardVerifier()
213		}
214	
215		fv := vp.forwardVerifiers[vp.index]
216		vp.index = (vp.index + 1) % vp.size
217	
218		return fv
219	}
220	
221	func (vp *VerifierPool) AcquireBackward() *BackwardVerifier {
222		if vp.backwardVerifiers[vp.index] == nil {
223			vp.backwardVerifiers[vp.index] = NewBackwardVerifier()
224		}
