	for i := 0; i < 4; i++ {
		binary.BigEndian.PutUint32(header[36+(i*4):], slots[i+8])
	}
	// Remaining MerkleRoot bytes (12 bytes) padded with zeros
	for i := 16; i < 20; i++ {
		header[36+i*4] = 0
		header[37+i*4] = 0
		header[38+i*4] = 0
		header[39+i*4] = 0
	}

