	binary.LittleEndian.PutUint32(header[72:76], BitcoinBits)

	// Bytes 76-80: Nonce (Big-Endian for SHA-256 word alignment)
	binary.BigEndian.PutUint32(header[76:80], nonce)

	return header
}

