// FindTopVarianceIndices finds the N indices with highest variance
func FindTopVarianceIndices(variances []float32, n int) []int {
	indices := make([]int, n)
	used := make(map[int]bool)

	for i := 0; i < n; i++ {
		maxVar := float32(-1.0)
		bestIdx := -1

		for j, v := range variances {
			if v > maxVar && !used[j] {
				maxVar = v
				bestIdx = j
			}
		}

		if bestIdx == -1 {
			break
		}

		indices[i] = bestIdx
		used[bestIdx] = true
	}

	return indices
}

